def transform(grid):
    h, w = len(grid), len(grid[0])

    # Solid horizontal bands: repeat the sequence of nonblank bands.
    if all(len(set(row)) == 1 for row in grid):
        bands = [(r, row[0]) for r, row in enumerate(grid) if row[0] != 0]
        if bands:
            period = len(bands)
            phases = {}
            for r, value in bands:
                phases[r % period] = value
            if len(phases) == period:
                return [[phases[r % period]] * w for r in range(h)]

    # Diagonal stripes. Choose the diagonal direction and shortest cycle
    # consistent with all the colored cells.
    candidates = []
    for direction in ("sum", "diff"):
        for period in range(1, max(h, w) + 1):
            phases = {}
            valid = True
            for r in range(h):
                for c in range(w):
                    value = grid[r][c]
                    if value == 0:
                        continue
                    k = (r + c) if direction == "sum" else (c - r)
                    phase = k % period
                    if phase in phases and phases[phase] != value:
                        valid = False
                        break
                    phases[phase] = value
                if not valid:
                    break
            if valid and len(phases) == period:
                candidates.append((period, direction, phases))
                break

    if candidates:
        _, direction, phases = min(candidates, key=lambda x: x[0])
        return [[phases[((r + c) if direction == "sum" else (c - r)) % len(phases)]
                 for c in range(w)] for r in range(h)]

    return [row[:] for row in grid]
